package com.hbm.satellite.cargo;
import com.hbm.satellite.*;import com.hbm.multiblock.MuffledMachine;import net.minecraft.core.*;import net.minecraft.nbt.*;import net.minecraft.network.chat.Component;import net.minecraft.world.*;import net.minecraft.world.entity.player.*;import net.minecraft.world.inventory.AbstractContainerMenu;import net.minecraft.world.item.ItemStack;import net.minecraft.world.level.block.entity.BlockEntity;import net.minecraft.world.level.block.state.BlockState;
/** Actual16slot cargo pad:15return slots+one frequency chip, independent source20tickphase. */
public final class SatelliteDockBlockEntity extends BlockEntity implements WorldlyContainer,MenuProvider,Nameable,MuffledMachine {
 private final NonNullList<ItemStack> slots=NonNullList.withSize(16,ItemStack.EMPTY);private Component customName;private boolean muffled,tilted;
 public SatelliteDockBlockEntity(BlockPos pos,BlockState state){super(SatelliteCargoContent.ENTITY.get(),pos,state);}
 public void tick(){if(!(level instanceof net.minecraft.server.level.ServerLevel server))return;int identity=(worldPosition.getY()+worldPosition.getZ()*27644437)*27644437+worldPosition.getX();long time=level.getGameTime()+identity;var chip=slots.get(15);if(time%20==0&&!chip.isEmpty()&&chip.getItem()==SatelliteContent.CHIP.get()){var sat=SatelliteSavedData.getData(server).getSatFromFreq(SatelliteFrequency.getFreqS(chip));if(sat!=null)sat.tryRequestItems(server,worldPosition.getX(),worldPosition.getY(),worldPosition.getZ());}}
 public ItemStack acceptCargo(ItemStack stack){for(int i=0;i<15&&!stack.isEmpty();i++){var current=slots.get(i);if(!current.isEmpty()&&ItemStack.isSameItemSameComponents(current,stack)){int amount=Math.min(stack.getCount(),current.getMaxStackSize()-current.getCount());if(amount>0){current.grow(amount);stack.shrink(amount);setChanged();}}}if(stack.isEmpty())return ItemStack.EMPTY;for(int i=0;i<15;i++)if(slots.get(i).isEmpty()){slots.set(i,stack);setChanged();return ItemStack.EMPTY;}return stack;}

 @Override public boolean isValidBlockState(BlockState state){return super.isValidBlockState(state)&&com.hbm.multiblock.DummyableBlock.isCore(state);}

 @Override public int getContainerSize(){return 16;}@Override public boolean isEmpty(){return slots.stream().allMatch(ItemStack::isEmpty);}@Override public ItemStack getItem(int slot){return slots.get(slot);}@Override public void setItem(int slot,ItemStack stack){slots.set(slot,stack);stack.limitSize(64);setChanged();}@Override public ItemStack removeItem(int slot,int count){var result=ContainerHelper.removeItem(slots,slot,count);if(!result.isEmpty())setChanged();return result;}@Override public ItemStack removeItemNoUpdate(int slot){return ContainerHelper.takeItem(slots,slot);}@Override public void clearContent(){slots.clear();setChanged();}@Override public boolean stillValid(Player player){return level!=null&&level.getBlockEntity(worldPosition)==this&&player.distanceToSqr(worldPosition.getX()+.5,worldPosition.getY()+.5,worldPosition.getZ()+.5)<=144;}
 @Override public boolean canPlaceItem(int slot,ItemStack stack){return slot==15;}@Override public int[] getSlotsForFace(Direction side){return java.util.stream.IntStream.range(0,15).toArray();}@Override public boolean canPlaceItemThroughFace(int slot,ItemStack stack,Direction side){return canPlaceItem(slot,stack);}@Override public boolean canTakeItemThroughFace(int slot,ItemStack stack,Direction side){return true;}
 @Override public Component getName(){return customName==null?Component.translatable("container.satDock"):customName;}@Override public Component getDisplayName(){return getName();}@Override public boolean hasCustomName(){return customName!=null;}@Override public Component getCustomName(){return customName;}public void setCustomName(Component name){customName=name;setChanged();}@Override public AbstractContainerMenu createMenu(int id,Inventory inventory,Player player){return new SatelliteDockMenu(id,inventory,this);}
 @Override public boolean isMuffled(){return muffled;}@Override public void setMuffled(boolean value){muffled=value;setChanged();}
 @Override protected void saveAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.saveAdditional(tag,lookup);var list=new ListTag();for(int i=0;i<16;i++)if(!slots.get(i).isEmpty()){var entry=(CompoundTag)slots.get(i).save(lookup);entry.putByte("slot",(byte)i);list.add(entry);}tag.put("items",list);if(customName!=null)tag.putString("name",Component.Serializer.toJson(customName,lookup));tag.putBoolean("muffled",muffled);tag.putBoolean("tilted",tilted);}
 @Override protected void loadAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.loadAdditional(tag,lookup);slots.clear();for(var value:tag.getList("items",Tag.TAG_COMPOUND)){var entry=(CompoundTag)value;int slot=entry.getByte("slot");if(slot>=0&&slot<16)slots.set(slot,ItemStack.parseOptional(lookup,entry));}muffled=tag.getBoolean("muffled");tilted=tag.getBoolean("tilted");customName=null;if(tag.contains("name")){var name=tag.getString("name");try{customName=Component.Serializer.fromJson(name,lookup);}catch(com.google.gson.JsonParseException ignored){customName=Component.literal(name);}if(customName==null&&!name.isEmpty())customName=Component.literal(name);}}
}
